  if isinstance(v,dict):
   for a,b in v.items():
    q=path+'/'+a
    print(q,type(b).__name__,len(json.dumps(b,ensure_ascii=False)))
    if isinstance(b,dict) and depth<3: walk(b,q,depth+1)
    if isinstance(b,list):
     for i,e in enumerate(b):
      if isinstance(e,dict): print(q+'/'+str(i),list(e.keys()))
  elif isinstance(v,list): print(path,len(v))
 walk(p[k],'/'+k)
PY"

